import {STAT_DATA as STAT} from './stat-data.mjs';
import {EDITOR_DATA as D} from './editor-data.mjs';
import {ITEMS} from './catalog.mjs';
import {nicknameBytes} from './extras.mjs';
export const NATURES=['Hardy','Lonely','Brave','Adamant','Naughty','Bold','Docile','Relaxed','Impish','Lax','Timid','Hasty','Serious','Jolly','Naive','Modest','Mild','Quiet','Bashful','Rash','Calm','Gentle','Sassy','Careful','Quirky'];
export const MOVES=Object.fromEntries(Object.entries(D.moves).filter(([id,m])=>m.name!=='Placeholder'));
export const HELD_ITEMS=Object.fromEntries([[0,{name:'ไม่ถือไอเทม'}],...Object.entries(ITEMS).filter(([id,m])=>Number(id)>0&&Number(id)<=1023&&m.pocket>=1&&m.pocket<=8)]);
const view=b=>new DataView(b.buffer,b.byteOffset,b.byteLength);
function genderOf(pid,ratio){return ratio===255?'none':ratio===254?'female':ratio===0?'male':(pid&255)<ratio?'female':'male'}
export function abilityChoices(mon,ctx){const data=D.species[mon.mapped],abilities=(ctx.flag(0x2f)?data?.altAbilities:data?.abilities)||[];return abilities.map((id,slot)=>({id,slot,name:D.abilities[id]||`Ability #${id}`})).filter(a=>a.id>0);}
export function readFields(mon,ctx){const b=mon.raw,v=view(b),ratio=D.species[mon.mapped]?.gender;return {shiny:!!(b[41]&128),gender:genderOf(v.getUint32(0,true),ratio),genderChoices:ratio===255?['none']:ratio===254?['female']:ratio===0?['male']:['male','female'],heldItem:v.getUint16(38,true)&1023,abilitySlot:(b[50]>>4)&3,abilities:abilityChoices(mon,ctx),moves:[v.getUint16(20,true)&1023,v.getUint16(24,true)&1023,(v.getUint32(24,true)>>>10)&1023,(v.getUint16(30,true)>>>1)&1023]};}
function setBits(v,offset,mask,shift,value,size=16){const old=size===32?v.getUint32(offset,true):v.getUint16(offset,true),next=((old&~(mask<<shift))|(value<<shift))>>>0;if(size===32)v.setUint32(offset,next,true);else v.setUint16(offset,next,true);}
function setPersonality(v,ratio,gender,nature){const old=v.getUint32(0,true),xor=(old>>>16)^(old&65535);if(genderOf(old,ratio)===gender&&old%25===nature)return;for(let step=1;step<=65536;step++){const lo=((old&65535)+step)&65535,pid=(((lo^xor)<<16)|lo)>>>0;if(genderOf(pid,ratio)===gender&&pid%25===nature){v.setUint32(0,pid,true);return}}throw Error('ไม่พบข้อมูลเพศและนิสัยที่คงสถานะ Shiny เดิมได้');}
export function updateFields(mon,change,ctx){const raw=mon.raw.slice(),v=view(raw),current=readFields(mon,ctx);if(mon.egg)throw Error('ยังไม่รองรับการแก้ข้อมูลไข่');if(change.nickname!==undefined&&change.nickname!==mon.nickname)raw.set(nicknameBytes(change.nickname),8);
if(change.level!==undefined){if(!Number.isInteger(change.level)||change.level<1||change.level>100)throw Error('เลเวลต้องเป็นจำนวนเต็ม 1–100');if(change.level!==mon.level){const growth=STAT.species[mon.mapped]?.growth,exp=STAT.experience[growth]?.[change.level];if(!Number.isInteger(exp)||exp<0||exp>0x1fffff)throw Error('ไม่รองรับตารางเลเวลของโปเกมอนตัวนี้');setBits(v,20,0x1fffff,10,exp,32);if(raw.length===76)raw[60]=change.level;}}
const gender=change.gender??current.gender,nature=change.nature??mon.nature;if(!current.genderChoices.includes(gender))throw Error('เพศนี้ไม่รองรับสำหรับโปเกมอนตัวนี้');if(!Number.isInteger(nature)||nature<0||nature>24)throw Error('เลือกนิสัยที่ถูกต้อง');
if(gender!==current.gender||nature!==mon.nature){const ratio=D.species[mon.mapped].gender;setPersonality(v,ratio,gender,nature);raw[39]=(raw[39]&~124)|(nature<<2);}
if(change.abilitySlot!==undefined&&change.abilitySlot!==current.abilitySlot){if(ctx.flag(0x3a))throw Error('เซฟนี้เปิดสุ่ม Ability จึงยังไม่รองรับการเปลี่ยน Ability');if(!current.abilities.some(a=>a.slot===change.abilitySlot))throw Error('เลือก Ability ที่มีในชนิดและฟอร์มนี้');raw[50]=(raw[50]&~48)|(change.abilitySlot<<4);}
if(change.heldItem!==undefined&&change.heldItem!==current.heldItem){if(!HELD_ITEMS[change.heldItem])throw Error('ไอเทมนี้ไม่รองรับการถือ');setBits(v,38,1023,0,change.heldItem);}
if(change.moves!==undefined){if(!Array.isArray(change.moves)||change.moves.length!==4||change.moves.some(id=>!Number.isInteger(id)||!MOVES[id])||change.moves.every(id=>id===0))throw Error('เลือกท่าที่รองรับอย่างน้อย 1 ท่า');const nonzero=change.moves.filter(Boolean);if(new Set(nonzero).size!==nonzero.length)throw Error('ท่าแต่ละช่องต้องไม่ซ้ำกัน');const layouts=[[20,0,16],[24,0,16],[24,10,32],[30,1,16]];change.moves.forEach((id,i)=>{if(id!==current.moves[i]){const [offset,shift,size]=layouts[i];setBits(v,offset,1023,shift,id,size);if(raw.length===76)raw[52+i]=id?1:0;}});}
if(change.shiny!==undefined){if(typeof change.shiny!=='boolean')throw Error('เลือกสถานะ Shiny ที่ถูกต้อง');raw[41]=(raw[41]&127)|(change.shiny?128:0);}
return raw;}
